#include "stdafx.h"#include "TrendsRsuKernelInfinite.h"#include <rsuPaths.h>#include <rsuErr.h>#include <TrendsDefines.h>HANDLE HandleT(bool bHeader, int index ){  char szFile[_MAX_PATH];  if( bHeader )  {    sprintf_s( szFile, "%s_Trends.hdr", rsuGetTrendPath() );  }  else  {    sprintf_s( szFile, "%s_Trends_%d.dat", rsuGetTrendPath(), index );  }  //  HANDLE hHandle = ::CreateFile( szFile,                                  GENERIC_READ|GENERIC_WRITE,                                  FILE_SHARE_READ|FILE_SHARE_WRITE,//|FILE_SHARE_DELETE,                                  NULL,                                  OPEN_ALWAYS,                                  FILE_ATTRIBUTE_ARCHIVE,                                  NULL );  return hHandle;}//bool KTrendsRsuKernelInfinite::OpenTrendHead(){  if( m_pHeadT )    return true;  //  HANDLE hVarFile = HandleT(true, 0);  if ( hVarFile != INVALID_HANDLE_VALUE )  {    DWORD dwSize = 1024*32*sizeof(STrendId);// 32000 имен    const DWORD varCount = Count();    if( varCount )    {      m_nSizeVar  = varCount * sizeof(float);      dwSize = varCount*sizeof(STrendId) + sizeof(CTrendHeader);      UINT64 needBytes = UINT64(m_nSizeVar) * ( m_FileDurationS / m_nInterval );      m_nSizeMB = needBytes / (1024*1024) + 1;      UINT64 testBytes = m_nSizeMB * (1024*1024);      ASSD( testBytes > needBytes );    }    //    m_hMapHead = ::CreateFileMapping( hVarFile, NULL, PAGE_READWRITE ,0, dwSize, FormatMappingHeaderTrends );    if ( m_hMapHead != NULL )    {      ::CloseHandle ( hVarFile );      m_pHeadT = (CTrendHeaderEx*)MapView( m_hMapHead, 0, dwSize );      ASS( m_pHeadT );            m_pHeadT->nVersion = CTrendHeader::vInfiniteTrends;      m_pHeadT->dwName = 0;      m_pHeadT->kBlk   = 0;      m_pHeadT->kVar   = 0;      m_pHeadT->kActualBlks[0] = m_pHeadT->kActualBlks[1] = 0;      m_nInterval = max(1,m_nInterval);      if ( m_nInterval < 1 )        m_pHeadT->StepTc = 1;      else        m_pHeadT->StepTc = m_nInterval;      //      return true;    }  }  DWORD Err = GetLastError();  ASS(FALSE);  return false;}//bool KTrendsRsuKernelInfinite::OpenTrendData(DWORD dwName){  DWORD index = dwName%2;  if( m_hMapData[index] )     ::CloseHandle( m_hMapData[index] );  m_hMapData[index] = NULL;  //  unsigned __int64 size = GetTrendSize();  DWORD dwLow  = DWORD(size);  DWORD dwHigh = DWORD(size>>32);  HANDLE hVarFile = HandleT( false, index );  if ( hVarFile != INVALID_HANDLE_VALUE )  {    char szName[32];    sprintf_s( szName, FormatMappingDataTrends, dwName);    //    m_hMapData[index] = ::CreateFileMapping( hVarFile, NULL, PAGE_READWRITE , dwHigh, dwLow, szName );    if( m_hMapData[index] != NULL )    {      ::CloseHandle( hVarFile );      return true;    }  }  //  // ::MessageBox( NULL, "Нет места на диске.\n"  //                     "Удалите лишнюю информацию на ж¸стком диске.\n"  //                     "И перезапустите модель.", "Ошибка", MB_ICONSTOP|MB_SYSTEMMODAL );  DWORD Err = ::GetLastError();  // LogMsg( "Ошибка OpenTrendData(DWORD dwName) '%d' '%d' low %lX high %lX", Err, dwName, dwLow, dwHigh );  // ASS(FALSE);  return false;}//// Запись в файл трендовvoid KTrendsRsuKernelInfinite::WriteTrends(){  if( !m_dwBlkAlloc )    m_dwBlkAlloc = maxBlocksOut;  if( m_pDataT == NULL )  {    UnmapViewOfFile( pbBegWnd );    DWORD dwBklTotal = m_dwBklTotal;    m_dwBklTotal = (m_dwBklTotal/m_dwBlkAlloc)*m_dwBlkAlloc;    MapTrends();    m_dwBklTotal = dwBklTotal;  }  else if ( (m_dwBklTotal % m_dwBlkAlloc) == 0 )  {    if( m_dwBklTotal )    {      UnmapViewOfFile( pbBegWnd );      MapTrends();    }  }  else if( m_AllocLeft < m_nSizeVar )  {    ASSD(0);    // Смена окна    UnmapViewOfFile( pbBegWnd );    MapTrends();  }  //  float * pTrend = m_pDataT;  if( !m_pDataT || IsBadWritePtr( m_pDataT, m_nSizeVar) )    return;  //  UINT nCount = Count();  STrendDef* list = Obj(0);  for ( UINT n = 0; n < nCount; n++ )  {    float v = 0;    switch ( list[n].eVal )    {    case enumValueDbl: v = (float)(*(double*)list[n].Void);break;    case enumValueInt: v = (float)(*(int   *)list[n].Void);break;    case enumValueChr: v = (float)(*(char  *)list[n].Void);break;    case enumValueBol:       if( -1!=list[n].bitOffset )        v = (*(int*)list[n].Void)&(1<<list[n].bitOffset) ? 1.f : 0;      else        v = (float)(*(bool  *)list[n].Void);      break;    case enumValueFlt: v = (float)(*(float *)list[n].Void);break;    }    *pTrend++ = v;  }  //  DWORD index = m_pHeadT->dwName % 2;  if( index < 2 )    m_pHeadT->kActualBlks[index]++;  m_dwBklTotal++;  m_pHeadT->kBlk++;  if( m_pHeadT->dwName>1 )    m_pHeadT->trendsStartTime += m_nInterval;  m_pDataT += nCount;  m_AllocLeft -= m_nSizeVar;}//UINT64 KTrendsRsuKernelInfinite::GetTrendSize(){  UINT64 r = m_nSizeMB;  r *= 1024;  r *= 1024;  SYSTEM_INFO SI;  GetSystemInfo( &SI );  DWORD dwAllocKvant = SI.dwAllocationGranularity;  UINT64 s = r;  s /= dwAllocKvant;  s *= dwAllocKvant;  return s;}// Смена окнаvoid KTrendsRsuKernelInfinite::MapTrends(){  float* curDataT = m_pDataT;  m_pDataT = NULL;  pbBegWnd = NULL;  //  SYSTEM_INFO SI;  GetSystemInfo( &SI );  //  SIZE_T StartAddr  = m_dwBklTotal * (SIZE_T)m_nSizeVar;  SIZE_T kPage      = StartAddr / SI.dwAllocationGranularity;  SIZE_T StartWnd   = kPage * SI.dwAllocationGranularity;   SIZE_T AllocSize  = (SIZE_T)m_nSizeVar * m_dwBlkAlloc;  SIZE_T AllocPages = AllocSize / SI.dwAllocationGranularity + 1;  AllocSize = AllocPages * SI.dwAllocationGranularity;  //  // Смена файла трендов  if( (StartWnd + AllocSize) >= GetTrendSize() )  {    m_pHeadT->dwName++;    OpenTrendData(m_pHeadT->dwName);    DWORD index = m_pHeadT->dwName % 2;    m_pHeadT->kActualBlks[index] = 0;    m_dwBklTotal = 0;    StartWnd = 0;    StartAddr = 0;  }  if( !m_dwBlkAlloc )    m_dwBlkAlloc = maxBlocksOut;  while( pbBegWnd == NULL )  {    DWORD err = GetLastError();    AllocSize  = (SIZE_T)m_nSizeVar * m_dwBlkAlloc;    AllocPages = AllocSize  / SI.dwAllocationGranularity + 1;    AllocSize  = AllocPages * SI.dwAllocationGranularity;    pbBegWnd = MapView( m_hMapData[m_pHeadT->dwName%2], StartWnd, AllocSize );    m_AllocLeft = AllocSize;    if( pbBegWnd )      break;    m_dwBlkAlloc -= 1;    if ( m_dwBlkAlloc == 0 )       return;// Это уже большая жопа  }  if( NULL==pbBegWnd )    return;  m_pDataT = (float*)(pbBegWnd + ( StartAddr - StartWnd ));  if ( pbBegWnd == NULL )  {    DWORD Err = GetLastError();    //LogMsg( "Ошибка MapTrends() '%d'", Err );    ASS(FALSE);  }}BYTE* KTrendsRsuKernelInfinite::MapView( HANDLE hHandle, UINT64 dwOffset, SIZE_T dwSize ){  ASSD( hHandle );  if( !hHandle )    return NULL;  DWORD dwLow  = dwOffset;  DWORD dwHigh = dwOffset>>32;  return (BYTE*)::MapViewOfFile( hHandle, FILE_MAP_ALL_ACCESS, dwHigh, dwLow, dwSize );}